1	// src/features/repository-context/domain/CandidateEvidence.ts
2	import type { EntryPointCandidate } from './EntryPointCandidate';
3	
4	export const candidateEvidenceKinds = [
5	  'dependency',
6	  'relatedTest',
7	  'gitCoChange',
8	  'directoryProximity',
9	  'markdownLink',
10	  'symbolSupport',
11	] as const;
12	
13	export type CandidateEvidenceKind = (typeof candidateEvidenceKinds)[number];
14	
15	export type CandidateEvidence = Readonly<{
16	  kind: CandidateEvidenceKind;
17	  projectId: string;
18	  candidatePath: string;
19	  relatedPath?: string;
20	  relatedSymbol?: string;
21	  score?: number;
22	  detail: string;
23	  startLine?: number;
24	  endLine?: number;
25	}>;
26	
27	export type CandidateEvidenceDiagnostic = Readonly<{
28	  kind: CandidateEvidenceKind;
29	  message: string;
30	}>;
31	
32	export type CandidateEvidenceBundle = Readonly<{
33	  projectId: string;
34	  candidatePath: string;
35	  evidence: readonly CandidateEvidence[];
36	  diagnostics: readonly CandidateEvidenceDiagnostic[];
37	}>;
38	
39	export type EnrichedEntryPointCandidate = Readonly<{
40	  candidate: EntryPointCandidate;
41	  evidence: readonly CandidateEvidence[];
42	  supportScore: number;
43	}>;
44	
45	const evidenceKey = (e: CandidateEvidence): string =>
46	  `${e.kind}:${e.projectId}:${e.candidatePath}:${e.relatedPath ?? ''}:${e.relatedSymbol ?? ''}:${e.startLine ?? 0}:${e.endLine ?? 0}`;
47	
48	export function sortCandidateEvidences(evidences: readonly CandidateEvidence[]): readonly CandidateEvidence[] {
49	  return [...evidences].sort((a, b) => {
50	    if (a.kind !== b.kind) return a.kind.localeCompare(b.kind);
51	    if ((a.relatedPath ?? '') !== (b.relatedPath ?? '')) {
52	      return (a.relatedPath ?? '').localeCompare(b.relatedPath ?? '');
53	    }
54	    if ((a.relatedSymbol ?? '') !== (b.relatedSymbol ?? '')) {
55	      return (a.relatedSymbol ?? '').localeCompare(b.relatedSymbol ?? '');
56	    }
57	    return (a.startLine ?? 0) - (b.startLine ?? 0);
58	  });
59	}
