    ];
    // 40 + 40 + 30 + 30 = 140 -> capped at 100
    expect(calculateCandidateSupportScore(evidences)).toBe(100);
  });

  it('stops counting evidence when category reaches its cap', () => {
    const evidences: CandidateEvidence[] = [
      { kind: 'directoryProximity', projectId: 'p1', candidatePath: 'A.ts', relatedPath: 'B.ts', detail: '' },
      { kind: 'directoryProximity', projectId: 'p1', candidatePath: 'A.ts', relatedPath: 'C.ts', detail: '' },
      { kind: 'directoryProximity', projectId: 'p1', candidatePath: 'A.ts', relatedPath: 'D.ts', detail: '' },
      { kind: 'directoryProximity', projectId: 'p1', candidatePath: 'A.ts', relatedPath: 'E.ts', detail: '' },
    ];
    // directoryProximity has cap of 1, so only first is counted: 10 * 1 = 10
    expect(calculateCandidateSupportScore(evidences)).toBe(10);
  });
});

