  });

  it('deduplicates and sorts evidences deterministically', () => {
    const evidences: CandidateEvidence[] = [
      { kind: 'symbolSupport', projectId: 'p1', candidatePath: 'A.ts', relatedSymbol: 'processOrder', startLine: 50, detail: '' },
