      { kind: 'symbolSupport', projectId: 'p1', candidatePath: 'A.ts', relatedSymbol: 'bar', detail: '' },
      { kind: 'symbolSupport', projectId: 'p1', candidatePath: 'A.ts', relatedSymbol: 'baz', detail: '' },
    ];
    // cap is 2 for symbolSupport (15 * 2 = 30), third item ignored
    expect(calculateCandidateSupportScore(evidences)).toBe(30);
  });

  it('caps markdownLink category at 2', () => {
