      { kind: 'markdownLink', projectId: 'p1', candidatePath: 'A.ts', relatedPath: 'D.md', detail: '' },
    ];
    // cap is 2 for markdownLink (10 * 2 = 20), third item ignored
    expect(calculateCandidateSupportScore(evidences)).toBe(20);
  });

  it('respects category cap when other categories contribute', () => {
    const evidences: CandidateEvidence[] = [
      { kind: 'dependency', projectId: 'p1', candidatePath: 'A.ts', relatedPath: 'B.ts', detail: '' },
      { kind: 'dependency', projectId: 'p1', candidatePath: 'A.ts', relatedPath: 'C.ts', detail: '' },
